function bookingTimes(DateTime, args, s) {
  const start = DateTime.fromISO(`${String(args.date).slice(0, 10)}T${String(args.time).slice(0, 5)}`, { zone: s.timezone });
  if (!start.isValid) return { ok: false, message: "That date or time is not valid." };
  if (start < DateTime.now().setZone(s.timezone)) return { ok: false, message: "That time is in the past." };
  const end = start.plus({ minutes: s.slotMinutes });
  return { ok: true, start: start.toISO(), end: end.toISO(), label: start.toFormat("cccc d LLLL 'at' HH:mm") };
}

const s = { ...$('Settings').first().json };
s.slotMinutes = Number(s.slotMinutes);
const call = $('Read tool calls').all().find((c) => c.json.name === 'book_appointment').json;
const events = $input.all().map((i) => i.json).filter((e) => e.id);
const times = bookingTimes(DateTime, call.args, s);
const free = times.ok && freeSlots(DateTime, events, call.args.date, s).slots.includes(String(call.args.time).slice(0, 5));
return [{ json: { ...call, ...times, free, caller_number: call.caller_number,
  message: times.ok ? (free ? '' : 'That time is not available. Check availability and offer another time.') : times.message }, pairedItem: { item: 0 } }];

